CREATE TABLE IF NOT EXISTS departments (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS doctors (id BIGSERIAL PRIMARY KEY, full_name VARCHAR(160) NOT NULL, department_id BIGINT REFERENCES departments(id) ON DELETE SET NULL, specialization VARCHAR(120), phone VARCHAR(40), email VARCHAR(160), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS nurses (id BIGSERIAL PRIMARY KEY, full_name VARCHAR(160) NOT NULL, department_id BIGINT REFERENCES departments(id) ON DELETE SET NULL, phone VARCHAR(40), email VARCHAR(160), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS patients (id BIGSERIAL PRIMARY KEY, full_name VARCHAR(160) NOT NULL, date_of_birth DATE, gender VARCHAR(20) CHECK (gender IN ('Male','Female','Other')), phone VARCHAR(40), email VARCHAR(160), address TEXT, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','DISCHARGED')), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rooms (id BIGSERIAL PRIMARY KEY, room_number VARCHAR(40) NOT NULL UNIQUE, room_type VARCHAR(40) NOT NULL DEFAULT 'General', daily_charge NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (daily_charge >= 0), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS admissions (id BIGSERIAL PRIMARY KEY, patient_id BIGINT NOT NULL REFERENCES patients(id), room_id BIGINT NOT NULL REFERENCES rooms(id), doctor_id BIGINT REFERENCES doctors(id) ON DELETE SET NULL, admission_date DATE NOT NULL DEFAULT CURRENT_DATE, discharge_date DATE, status VARCHAR(20) NOT NULL DEFAULT 'ADMITTED' CHECK (status IN ('ADMITTED','DISCHARGED')), CHECK (discharge_date IS NULL OR discharge_date >= admission_date));
CREATE UNIQUE INDEX IF NOT EXISTS uq_active_admission_room ON admissions(room_id) WHERE status='ADMITTED';
CREATE TABLE IF NOT EXISTS medicines (id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL, quantity INTEGER NOT NULL DEFAULT 0 CHECK (quantity >= 0), unit_price NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (unit_price >= 0), expiry_date DATE, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bills (id BIGSERIAL PRIMARY KEY, patient_id BIGINT NOT NULL REFERENCES patients(id), admission_id BIGINT REFERENCES admissions(id) ON DELETE SET NULL, description TEXT NOT NULL, amount NUMERIC(12,2) NOT NULL CHECK (amount >= 0), payment_status VARCHAR(20) NOT NULL DEFAULT 'UNPAID' CHECK (payment_status IN ('UNPAID','PAID','WAIVED')), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attendance (id BIGSERIAL PRIMARY KEY, staff_type VARCHAR(20) NOT NULL CHECK (staff_type IN ('DOCTOR','NURSE')), staff_id BIGINT NOT NULL, attendance_date DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(20) NOT NULL CHECK (status IN ('PRESENT','ABSENT','LEAVE')), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(staff_type,staff_id,attendance_date));
